record.field:
# Trong server action code
for task in records:
    if not task.nhan_vien_phu_trach_ids or not task.ngay_kt:
        continue
    partners = task.nhan_vien_phu_trach_ids.mapped('user_id.partner_id')
    if not partners:
        continue
    # Lấy sự kiện hiện có (nếu có)
    event = task.calendar_event_id
    vals = {
        'name': f"Công việc: {task.ten_cv}",
        'description': f"Mô tả: {task.mo_ta or ''}\nDự án: {task.du_an_id.name}",
        'start': task.ngay_kt,
        'stop': task.ngay_kt,
        'allday': True,
        'partner_ids': [(6, 0, partners.ids)],
        'user_id': task.nhan_vien_phu_trach_ids[0].user_id.id or env.user.id,
    }
    if event:
        event.write(vals)
    else:
        event = env['calendar.event'].create(vals)
        task.write({'calendar_event_id': event.id})
